/**
 * messy-company-v1 page plan: one brief per page, written before any text.
 *
 * Each brief names the page's kind, date, writer, focus accounts, the facts
 * it must carry and the exact phrases it must use. Owner-phrase mentions are
 * resolved by the oracle from the world plan, so the gold label for each one
 * exists before a model writes the sentence that holds it.
 */
import { resolveOwner, surfaceFor, windowRelation, type OwnerForm, type Reason } from './oracle.ts';
import { ACCOUNTS, RECORDS, SPLIT_OF, accountById, displayName, personById, type ClusterId, type RecordDoc, type Split } from './world.ts';

export type Kind = 'profile' | 'record' | 'email' | 'chat' | 'meeting' | 'ticket' | 'crm' | 'weekly' | 'agent-note' | 'private-note' | 'note';
export type AuthorModel = 'openai:gpt-6.1-sol' | 'gemini:gemini-4-argon';
export const AUTHORS: AuthorModel[] = ['openai:gpt-6.1-sol', 'gemini:gemini-4-argon'];

export interface MentionPlan {
  owner?: string;
  form?: OwnerForm;
  surface?: string;
  /** Explicit labels for phrases the oracle does not resolve (non-owner possessives, contacts, vendors). */
  explicit?: { accounts: string[]; reason: Reason; note: string };
}

export interface ResolvedMention {
  mid: string;
  surface: string;
  owner: string | null;
  form: string;
  accounts: string[];
  should_link: boolean;
  should_link_public: boolean;
  reason: Reason;
  window_relation: string;
  date_basis: 'frontmatter' | 'body' | 'undated';
  stints: string[];
  instruction: string;
}

export interface PageSpec {
  slug: string;
  cluster: ClusterId;
  split: Split;
  kind: Kind;
  type: string;
  title: string;
  date: string | null;
  /** The date the body states for the event when it conflicts with the frontmatter date. */
  body_date?: string;
  status?: 'draft' | 'unsigned' | 'signed';
  visibility?: 'private';
  writer: string;
  accounts: string[];
  brief: string;
  mentions: ResolvedMention[];
  events: string[];
  claims: string[];
  retraction?: string;
  states_stints: string[];
  record?: string;
  aliases: string[];
  entity_intent: Record<string, string>;
  author: AuthorModel;
  style: { voice: string; date_format: string; typos: number; length_words: number; format: string };
}

interface Raw {
  s: string; k: Kind; d: string | null; by: string; acc: string[]; t: string; b: string;
  m?: MentionPlan[]; ev?: string[]; cl?: string[]; rt?: string; own?: string[]; vis?: 'private'; bd?: string; len?: number; fmt?: string; al?: string[]; author?: AuthorModel;
  /** Intended entity for colliding or look-alike surfaces used on this page ('mixed' = per occurrence). */
  ent?: Record<string, string>;
}

const o = (owner: string, form: OwnerForm): MentionPlan => ({ owner, form });
const x = (surface: string, reason: Reason, note: string, accounts: string[] = [], owner?: string): MentionPlan => ({ surface, owner, explicit: { accounts, reason, note } });

const TYPE: Record<Kind, string> = { profile: 'company', record: 'deal', email: 'email', chat: 'slack', meeting: 'meeting', ticket: 'note', crm: 'note', weekly: 'note', 'agent-note': 'note', 'private-note': 'note', note: 'note' };

