const CLUSTERS: Record<ClusterId, Raw[]> = { north: NORTH, central: CENTRAL, coastal: COASTAL, strategic: STRATEGIC };

// ─── Record pages ───────────────────────────────────────────────────

function recordSlug(r: RecordDoc): string {
  const d = r.signed ?? r.drafted;
  return `contracts/${d}-${r.id.replace(/^r-/, '')}`;
}

const ATTR_LABEL: Record<string, string> = { seats: 'subscribed seats', price_per_seat: 'price per seat per year (USD)', discount_pct: 'discount (%)', renewal_date: 'end of the current term (renewal date)', sla_tier: 'support SLA tier', notice_days: 'days of advance written notice to stop the agreement continuing', payment_terms_days: 'payment terms (net days)' };

function recordBrief(r: RecordDoc): string {
  const acctNames = r.accounts.map(a => displayName(a, r.signed ?? r.drafted));
  const values = r.sets.map(s => `${ATTR_LABEL[s.attr]} = ${s.value}${s.scope.length < r.accounts.length || r.accounts.length > 1 ? ` (applies to ${s.scope.map(a => displayName(a, r.signed ?? r.drafted)).join(' and ')})` : ''}`).join('; ');
  const status = r.status === 'signed'
    ? `Executed: include a signature block signed on ${r.signed} by both parties (customer signatory plus June Osei-Lark for Pemberline).`
    : r.status === 'draft'
      ? `This is a DRAFT, never signed: mark it as a draft in the body (e.g. a draft header or watermark line) and leave signature lines blank.`
      : `This version was never countersigned: the body must make clear it is unsigned (blank or missing signature lines, a note such as "unsigned" or "for review"). Do not call it a draft.`;
  const eff = r.effective ? ` Effective date ${r.effective}${r.signed && r.signed !== r.effective ? ` (signed ${r.signed}; state both dates and keep them distinct)` : ''}.` : '';
  const sup = r.supersedes?.length ? ` It changes earlier paperwork for this customer; refer to the earlier agreement generically.` : '';
  const partial = r.note?.includes('Partial override') ? ' Say explicitly that only the listed terms change for that company and every other term of the parent agreement continues to apply to it.' : '';
  const carry = r.note && /carr(y|ies) over|not restated|Leaves/.test(r.note) ? ` ${r.note}` : '';
  return `${r.title}. Parties: Pemberline Systems and ${acctNames.join(' and its affiliate ')}. Drafted ${r.drafted}.${eff} Terms this document sets: ${values}. ${status}${sup}${partial}${carry}`;
}

// ─── Assembly ───────────────────────────────────────────────────────

function hash(s: string): number {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619) >>> 0;
  return h;
}

const VOICES = ['terse and practical', 'chatty, a bit rambling', 'polished and businesslike', 'hurried, lots of fragments', 'friendly and organized', 'dry and slightly sarcastic'];
const DATE_FORMATS = ['ISO (2025-06-02)', 'US long (June 2, 2025)', 'US short (6/2/25)', 'day-month (2 Jun 2025)', 'casual (Jun 2nd, Monday the 2nd)', 'mixed: some ISO, some casual'];
const FORMAT_BY_KIND: Record<Kind, string[]> = {
  profile: ['a header block of key fields as a table, then short sections', 'bulleted fact sheet with a short history section'],
  record: ['formal numbered sections and a signature block'],
  email: ['an email thread with From/To/Date headers and quoted earlier replies (> lines)', 'a single email with a forwarded message below'],
  chat: ['a chat log with [HH:MM] timestamps and lowercase usernames', 'a chat export with "Name  10:42 AM" lines'],
  meeting: ['meeting notes with attendees, bullets and action items', 'loose call notes, half sentences, an action list at the end'],
  ticket: ['a ticket with a fields table and a timestamped update log'],
  crm: ['a terse CRM activity note with a few key: value fields', 'a short CRM note in two paragraphs'],
  weekly: ['a weekly update with a section per topic and bullets', 'a weekly update with a short status table and notes'],
  'agent-note': ['an assistant-written digest with headings and bullets, addressed to Ruth', 'a short assistant memo with a "what changed" list'],
  'private-note': ['private notes in first person, bullets'],
  note: ['a short internal note', 'a checklist with a few lines of context'],
};

function lengthFor(k: Kind, h: number): number {
  const base: Record<Kind, [number, number]> = { profile: [180, 320], record: [700, 1300], email: [150, 420], chat: [160, 380], meeting: [200, 450], ticket: [150, 320], crm: [80, 200], weekly: [250, 520], 'agent-note': [180, 380], 'private-note': [150, 300], note: [100, 250] };
  const [lo, hi] = base[k];
  return lo + (h % (hi - lo));
}

function mentionInstruction(m: Omit<ResolvedMention, 'instruction' | 'mid'>, date: string | null, privateTarget: boolean): string {
  const q = `"${m.surface}"`;
  if (m.form === 'explicit') {
    return m.accounts.length
      ? `Use the exact phrase ${q} once, meaning ${m.reason === 'contact_employer' ? m.accounts.map(a => displayName(a, date)).join(', ') : ''} (${m.reason.replace(/_/g, ' ')}). Don't add a gloss explaining it.`
      : `Use the exact phrase ${q} once, in the sense of: ${NOTE_OF.get(m.surface + '|' + m.reason) ?? ''}. It must not be about a customer account.`;
  }
  if (m.should_link) {
    const names = m.accounts.map(a => displayName(a, date)).join(' and ');
    const hide = privateTarget ? ` This page must not reveal which account that is or who manages it: no account name, location, or detail that identifies it in that sentence or paragraph.` : ` Don't put the account's name in the same sentence; the reader should work it out.`;
    return `Use the exact phrase ${q} once, referring to ${names}.${hide}`;
  }
  if (m.reason === 'ambiguous_two_owned' || m.reason === 'undated_ambiguous') {
    return `Use the exact phrase ${q} once, but vaguely: the writer does not say which account it is, and nothing nearby (name, location, numbers, products) may identify one. Keep that sentence generic, like a passing comment.`;
  }
  return `Use the exact phrase ${q} once, as a passing remark that does not identify any specific account.`;
}
const NOTE_OF = new Map<string, string>();

export function buildPages(): PageSpec[] {
  const out: PageSpec[] = [];
  for (const cluster of ['north', 'central', 'coastal', 'strategic'] as ClusterId[]) {
    const raws: Raw[] = [...CLUSTERS[cluster]];
    for (const r of RECORDS.filter(r => accountById(r.accounts[0]).cluster === cluster)) {
      raws.push({ s: recordSlug(r), k: 'record', d: r.signed ?? r.drafted, by: 'june-osei', acc: r.accounts, t: r.title, b: recordBrief(r), ev: [] });
    }
    raws.sort((a, b) => a.s.localeCompare(b.s));
    raws.forEach((raw, i) => {
      const h = hash(raw.s);
      const record = raw.k === 'record' ? RECORDS.find(r => recordSlug(r) === raw.s)! : undefined;
      const dateBasis = raw.bd ?? raw.d;
      const mentions: ResolvedMention[] = (raw.m ?? []).map((mp, j) => {
        const mid = `${raw.s}#m${j + 1}`;
        if (mp.explicit) {
          NOTE_OF.set(mp.surface! + '|' + mp.explicit.reason, mp.explicit.note);
          const base = { surface: mp.surface!, owner: mp.owner ?? null, form: 'explicit', accounts: mp.explicit.accounts, should_link: mp.explicit.accounts.length > 0, should_link_public: mp.explicit.accounts.length > 0, reason: mp.explicit.reason, window_relation: dateBasis ? 'n/a' : 'undated', date_basis: (raw.bd ? 'body' : raw.d ? 'frontmatter' : 'undated') as ResolvedMention['date_basis'], stints: [] };
          return { mid, ...base, instruction: mentionInstruction(base, dateBasis, false) };
        }
        const full = resolveOwner(mp.owner!, mp.form!, dateBasis);
        const pub = resolveOwner(mp.owner!, mp.form!, dateBasis, 'public');
        const shouldLink = full.accounts.length > 0;
        const publicSame = shouldLink && pub.accounts.length === full.accounts.length && pub.accounts.every(a => full.accounts.includes(a));
        const base = {
          surface: surfaceFor(mp.owner!, mp.form!), owner: mp.owner!, form: mp.form!.form, accounts: full.accounts, should_link: shouldLink,
          should_link_public: publicSame && raw.vis !== 'private', reason: full.reason,
          window_relation: shouldLink ? windowRelation(full.stints, dateBasis) : (dateBasis ? 'n/a' : 'undated'),
          date_basis: (raw.bd ? 'body' : raw.d ? 'frontmatter' : 'undated') as ResolvedMention['date_basis'], stints: full.stints,
        };
        return { mid, ...base, instruction: mentionInstruction(base, dateBasis, shouldLink && !publicSame) };
      });
      const author: AuthorModel = raw.author ?? (record?.long ? (cluster === 'north' ? AUTHORS[1] : AUTHORS[0]) : AUTHORS[(i + (cluster === 'central' || cluster === 'strategic' ? 1 : 0)) % 2]);
      const formats = FORMAT_BY_KIND[raw.k];
      out.push({
        slug: raw.s, cluster, split: SPLIT_OF[cluster], kind: raw.k, type: TYPE[raw.k], title: raw.t, date: raw.d,
        ...(raw.bd ? { body_date: raw.bd } : {}),
        ...(record && record.status_in_frontmatter ? { status: record.status } : {}),
        ...(raw.vis ? { visibility: raw.vis } : {}),
        writer: raw.by, accounts: raw.acc, brief: raw.k === 'weekly' && raw.by === 'moss' ? `Moss compiles this team weekly from the team lead's notes; write it as Moss's compiled update. ${raw.b}` : raw.b, mentions, events: raw.ev ?? [], claims: raw.cl ?? [],
        ...(raw.rt ? { retraction: raw.rt } : {}),
        states_stints: raw.own ?? [], ...(record ? { record: record.id } : {}), aliases: raw.al ?? [], entity_intent: raw.ent ?? {}, author,
        style: {
          voice: raw.k === 'record' ? 'formal legal drafting' : raw.by === 'moss' ? 'an AI assistant: neat, factual, a little stiff' : VOICES[h % VOICES.length],
          date_format: DATE_FORMATS[(h >> 3) % DATE_FORMATS.length],
          typos: raw.k === 'record' ? 0 : (h >> 5) % 3,
          length_words: record?.long ? 4200 : (raw.len ?? lengthFor(raw.k, h >> 7)),
          format: raw.fmt ?? formats[(h >> 9) % formats.length],
        },
      });
    });
  }
  return out;
}

export function accountsInCluster(c: ClusterId): string[] {
  return ACCOUNTS.filter(a => a.cluster === c).map(a => a.id);
}
export { personById };
